extends Node3D
class_name GeneticProgramming

@export var population_size: int = 20
var _population: Array[Genome] = []

func _init_population() -> void:
	_population.clear()
	for i in population_size:
		var g = Genome.new()
		g.random_init(genome_complexity, genome_type)
		_population.append(g)

	# Display in a grid
	for i in population_size:
		var pheno = _population[i].decode()
		var row = i / 5
		var col = i % 5
		pheno.position = Vector3(col * spacing, 0, row * spacing)
		add_child(pheno)

@export_enum("Volume", "Height", "Symmetry", "Sphere", "Custom") var fitness_function: int = 0

func _evaluate_fitness(g: Genome) -> float:
	var pheno = g.decode()
	match fitness_function:
		0:  # Volume
			return 1.0 - absf(_compute_volume(pheno) - target_volume)
		1:  # Height
			return 1.0 - absf(_compute_height(pheno) - target_height)
		2:  # Symmetry
			return _compute_symmetry(pheno)
		3:  # Sphere-likeness
			return _compute_spherelike(pheno)
		_:  # Custom
			return _compute_custom(pheno)

# The fitness function is the whole story.
# Change it → evolution goes somewhere else.

@export var mutation_rate: float = 0.3
@export var crossover_rate: float = 0.7

func _crossover(parent_a: Genome, parent_b: Genome) -> Genome:
	var child = Genome.new()
	child.genes.resize(parent_a.genes.size())
	var cut = randi() % parent_a.genes.size()
	for i in range(parent_a.genes.size()):
		child.genes[i] = parent_a.genes[i] if i < cut else parent_b.genes[i]
	return child

func _mutate(g: Genome) -> void:
	for i in range(g.genes.size()):
		if randf() < mutation_rate:
			g.genes[i] += randf_range(-0.2, 0.2)
			g.genes[i] = clampf(g.genes[i], -1.0, 1.0)

# The edge of chaos is at mutation_rate ~0.3:
# low enough to preserve good genomes across generations,
# high enough to keep exploring.

@export var elitism_count: int = 2

func _evolve_one_generation() -> void:
	# 1. Evaluate all
	for g in _population:
		g.fitness = _evaluate_fitness(g)

	# 2. Sort by fitness (descending)
	_population.sort_custom(func(a, b): return a.fitness > b.fitness)

	# 3. Elitism: top N survive unchanged
	var next_gen: Array[Genome] = []
	for i in range(elitism_count):
		next_gen.append(_population[i])

	# 4. Fill rest via tournament + crossover + mutation
	while next_gen.size() < population_size:
		var parent_a = _tournament_select()
		var parent_b = _tournament_select()
		var child = _crossover(parent_a, parent_b)
		_mutate(child)
		next_gen.append(child)

	_population = next_gen
